import{_ as a,o as r,c as o,a3 as f}from"./chunks/framework.CJlOecQn.js";const d=JSON.parse('{"title":"الهاتف والإنترنت","description":"مشغلو الاتصالات المرخصون في قطر، وكيف تحصل على شريحة، والإنترنت المنزلي بالألياف، وكيف تقدم شكوى إلى المشغل ثم إلى الجهة المنظمة.","frontmatter":{"title":"الهاتف والإنترنت","description":"مشغلو الاتصالات المرخصون في قطر، وكيف تحصل على شريحة، والإنترنت المنزلي بالألياف، وكيف تقدم شكوى إلى المشغل ثم إلى الجهة المنظمة.","lastChecked":"2026-10","sourceCount":11},"headers":[],"relativePath":"ar/guide/phone-and-internet.md","filePath":"ar/guide/phone-and-internet.md"}'),n={name:"ar/guide/phone-and-internet.md"};function t(s,e,l,i,c,p){return r(),o("div",null,[...e[0]||(e[0]=[f('<h1 id="الهاتف-والإنترنت" tabindex="-1">الهاتف والإنترنت <a class="header-anchor" href="#الهاتف-والإنترنت" aria-label="Permalink to &quot;الهاتف والإنترنت&quot;">​</a></h1><p>تقدم خدمات الهاتف المحمول والخدمات الثابتة في قطر شركتان: Ooredoo وفودافون. وتدرج هيئة تنظيم الاتصالات الشركتين ضمن المرخص لهم في الخدمات المتنقلة والثابتة، كما تدرج شبكة قطر الوطنية للنطاق العريض ضمن تراخيص الخدمات الثابتة غير النشطة.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><h2 id="الحصول-على-شريحة" tabindex="-1">الحصول على شريحة <a class="header-anchor" href="#الحصول-على-شريحة" aria-label="Permalink to &quot;الحصول على شريحة&quot;">​</a></h2><p><strong>ما تحتاج إليه.</strong> تطلب شروط Ooredoo عند شراء الخدمة البطاقة الشخصية القطرية أو بطاقة هوية خليجية أو جواز السفر، أصلية وسارية. وإذا اشتريت الخدمة لشخص آخر فيلزم إبراز المستندات الأصلية لكما معًا.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> أما فودافون فتطلب جواز السفر أو البطاقة الشخصية القطرية السارية للخط مسبق الدفع، والبطاقة الشخصية القطرية للخط الآجل الدفع.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><p><strong>أين تشتري.</strong> تبيع فودافون شريحة Instant SIM في أكثر من 2,600 موقع، وتفعّلها بنفسك: أدخل الشريحة، وامسح رمز QR، واختر الباقة، ثم امسح بطاقتك الشخصية أو جوازك، ووقع على الشروط.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></p><p><strong>مسبق الدفع أم آجل الدفع.</strong> في الخط مسبق الدفع تشحن رصيدك متى شئت، وخدمة Ooredoo مسبقة الدفع اسمها هلا.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup> أما الخط الآجل الدفع فباقة شهرية، وباقات Ooredoo منها هي شهري+ وقطرنا+.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup> راجع موقعي الشركتين لمعرفة الأسعار الحالية، فالباقات والعروض تتغير.<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6]</a></sup></p><h2 id="حافظ-على-الرقم-المرتبط-ببطاقتك-الشخصية" tabindex="-1">حافظ على الرقم المرتبط ببطاقتك الشخصية <a class="header-anchor" href="#حافظ-على-الرقم-المرتبط-ببطاقتك-الشخصية" aria-label="Permalink to &quot;حافظ على الرقم المرتبط ببطاقتك الشخصية&quot;">​</a></h2><p>تستخدم التطبيقات الحكومية مثل مطراش الرقم المرتبط ببطاقتك الشخصية القطرية، فانتبه عند تغيير الخط أو مشاركته.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup> وترسل Ooredoo رسالة نصية إلى الرقم الأساسي المرتبط ببطاقتك عند تفعيل خدمة جديدة، ولديك 7 أيام لإبلاغها إذا لم تكن قد طلبت الخدمة.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><h2 id="الإنترنت-المنزلي" tabindex="-1">الإنترنت المنزلي <a class="header-anchor" href="#الإنترنت-المنزلي" aria-label="Permalink to &quot;الإنترنت المنزلي&quot;">​</a></h2><p>الشركتان مرخصتان للخدمات الثابتة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup> التفاصيل التالية خاصة بفودافون، فاطرح الأسئلة نفسها على Ooredoo قبل أن تقارن.</p><ul><li>اطلب التحقق من توفر الخدمة أولًا. تتيح فودافون ذلك عبر المحادثة أو طلب معاودة الاتصال.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></li><li>تتطلب ألياف Vodafone Home أن يكون المبنى موصولًا بشبكتها. وإذا لم يكن موصولًا فهي تعرض باقات Vodafone Home 5G.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></li><li>يمكنك الاشتراك عبر الموقع أو واتساب أو المتجر أو الهاتف.<sup class="footnote-ref"><a href="#fn8" id="fnref8:1">[8]</a></sup></li><li>تتصل بك فودافون لتحديد موعد التركيب، ولتغييره لاحقًا استخدم تطبيق My Vodafone أو اتصل بالرقم 111.<sup class="footnote-ref"><a href="#fn8" id="fnref8:2">[8]</a></sup></li><li>اقرأ شرط الالتزام. تشترط فودافون سداد ثلاث فواتير شهرية على الأقل، وتفرض 798 ريالًا قطريًا إذا ألغيت الخدمة قبل مرور اثني عشر شهرًا.<sup class="footnote-ref"><a href="#fn8" id="fnref8:3">[8]</a></sup></li><li>عند الانتقال إلى سكن جديد، تكون نقلة واحدة كل 12 شهرًا مجانية، أما النقلة الثانية خلال المدة نفسها فتكلف 200 ريال قطري.<sup class="footnote-ref"><a href="#fn8" id="fnref8:4">[8]</a></sup></li></ul><h2 id="تغيير-المشغل" tabindex="-1">تغيير المشغل <a class="header-anchor" href="#تغيير-المشغل" aria-label="Permalink to &quot;تغيير المشغل&quot;">​</a></h2><p>يمكنك نقل رقم الهاتف المحمول أو الرقم الثابت إلى المشغل الآخر.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup> وفي الرقم الثابت عليك سداد جميع الفواتير المستحقة أولًا. وقد يترتب على إنهاء الخدمة الثابتة مبكرًا رسوم إضافية، فاقرأ شروطك.<sup class="footnote-ref"><a href="#fn9" id="fnref9:1">[9]</a></sup></p><h2 id="تقديم-شكوى" tabindex="-1">تقديم شكوى <a class="header-anchor" href="#تقديم-شكوى" aria-label="Permalink to &quot;تقديم شكوى&quot;">​</a></h2><p>ابدأ بالمشغل. تقول هيئة تنظيم الاتصالات إن على المشغلين حل المشكلات الصحيحة، وتطلب شروط Ooredoo منحها فرصة لمعالجة المشكلة قبل التوجه إلى جهة أخرى.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup><sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></p><ol><li>قدم الشكوى عبر متجر المشغل أو مركز الاتصال أو موقعه، واحتفظ برقم الشكوى، فنموذج الهيئة يطلبه.<sup class="footnote-ref"><a href="#fn10" id="fnref10:1">[10]</a></sup></li><li>اعترض على الفاتورة بسرعة. تمنحك شروط Ooredoo مهلة 45 يومًا من تاريخ إصدار الفاتورة.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li><li>توجه إلى الهيئة إذا بقيت شكوى انقطاع الخدمة المتنقلة دون حل 48 ساعة، أو انقطاع الخدمة الثابتة 72 ساعة، أو أي شكوى أخرى 30 يومًا تقويميًا. ويمكنك التوجه إليها في أي وقت إذا أغلق المشغل الشكوى ولم ترض عن الحل.<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup></li></ol><p>قنوات الشكوى لدى الهيئة هي <a href="https://www.cra.gov.qa/en/services/lodge-a-complaint" target="_blank" rel="noreferrer">النموذج الإلكتروني</a>، والخط الساخن 103 على مدار الساعة، والبريد الإلكتروني <a href="mailto:consumervoice@cra.gov.qa" target="_blank" rel="noreferrer">consumervoice@cra.gov.qa</a>، وتطبيق أرسل، أو زيارة مقرها في برج النصر (ب).<sup class="footnote-ref"><a href="#fn11" id="fnref11:1">[11]</a></sup></p><p>تحقق الهيئة في الشكوى وقد تطلب منك مزيدًا من التفاصيل، ولا تكشف هويتك وتفاصيل شكواك للمشغل إلا بموافقتك.<sup class="footnote-ref"><a href="#fn10" id="fnref10:2">[10]</a></sup></p><p>انظر أيضًا: <a href="./metrash">مطراش</a>، <a href="./housing-and-utilities">السكن والخدمات</a>.</p><h2 id="المصادر" tabindex="-1">المصادر <a class="header-anchor" href="#المصادر" aria-label="Permalink to &quot;المصادر&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>هيئة تنظيم الاتصالات، <a href="https://www.cra.gov.qa/en/Services/Telecommunications/Licensing/Licensees" target="_blank" rel="noreferrer">المرخص لهم</a>. آخر تحقق: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn2" class="footnote-item"><p>Ooredoo قطر، <a href="https://www.ooredoo.qa/web/en/general-terms-and-conditions-for-consumer-services/" target="_blank" rel="noreferrer">الشروط والأحكام العامة</a>. آخر تحقق: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn3" class="footnote-item"><p>فودافون قطر، <a href="https://www.vodafone.qa/en/help/faqs" target="_blank" rel="noreferrer">المساعدة والأسئلة الشائعة</a>. آخر تحقق: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn4" class="footnote-item"><p>فودافون قطر، <a href="https://www.vodafone.qa/instant-sim" target="_blank" rel="noreferrer">Instant SIM</a>. آخر تحقق: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn5" class="footnote-item"><p>Ooredoo قطر، <a href="https://www.ooredoo.qa/web/en/prepaid-plans/" target="_blank" rel="noreferrer">الباقات مسبقة الدفع</a>. آخر تحقق: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn6" class="footnote-item"><p>Ooredoo قطر، <a href="https://www.ooredoo.qa/web/en/postpaid-plans/" target="_blank" rel="noreferrer">الباقات الآجلة الدفع</a>. آخر تحقق: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn7" class="footnote-item"><p>فودافون قطر، <a href="https://www.vodafone.qa/en/services/home/gigahome" target="_blank" rel="noreferrer">الإنترنت المنزلي</a>. آخر تحقق: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn8" class="footnote-item"><p>فودافون قطر، <a href="https://www.vodafone.qa/en/faqs/GigaHome" target="_blank" rel="noreferrer">الأسئلة الشائعة عن Vodafone Home</a>. آخر تحقق: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref8:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref8:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref8:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref8:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn9" class="footnote-item"><p>هيئة تنظيم الاتصالات، <a href="https://www.cra.gov.qa/en/press-releases/telecom-consumers-can-transfer-their-fixed-numbers-from-one-service-provider-to-another" target="_blank" rel="noreferrer">نقل الأرقام الثابتة بين مقدمي الخدمة</a>. آخر تحقق: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref9:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn10" class="footnote-item"><p>هيئة تنظيم الاتصالات، <a href="https://www.cra.gov.qa/en/services/lodge-a-complaint" target="_blank" rel="noreferrer">تقديم شكوى</a>. آخر تحقق: 2026-10. <a href="#fnref10" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref10:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref10:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn11" class="footnote-item"><p>هيئة تنظيم الاتصالات، <a href="https://www.cra.gov.qa/en/press-releases/cra-launches-telecom-complaints-management-system" target="_blank" rel="noreferrer">إطلاق نظام إدارة شكاوى الاتصالات</a>. آخر تحقق: 2026-10. <a href="#fnref11" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref11:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li></ol></section>',22)])])}const u=a(n,[["render",t]]);export{d as __pageData,u as default};
